  const result = {};
  const lines = String(text).split(/\r\n|[\n\r]/);

  for (const line of lines) {
    let i = 0;
    const n = line.length;
    const isWs = (c) => c === ' ' || c === '\t';
    const skipWs = () => { while (i < n && isWs(line[i])) i++; };

    skipWs();
    if (i >= n || line[i] === '#') continue;

    let key = '';
    while (i < n && !isWs(line[i]) && line[i] !== '=' && line[i] !== '#' && line[i] !== '"') {
      key += line[i++];
    }
    if (!key) continue;

    skipWs();
    if (line[i] !== '=') continue;
    i++;
    skipWs();

    let value = null;
    if (line[i] === '"') {
      i++;
      let out = '';
      let closed = false;
      while (i < n) {
        const c = line[i];
        if (c === '\\') {
          const e = line[i + 1];
          if (e === 'n') { out += '\n'; i += 2; }
          else if (e === '"') { out += '"'; i += 2; }
          else if (e === '\\') { out += '\\'; i += 2; }
          else if (e === undefined) { i = n; }
          else { out += c + e; i += 2; }
        } else if (c === '"') {
          closed = true;
          i++;
          break;
        } else {
          out += c;
          i++;
        }
      }
      if (!closed) continue;
      value = out;
    } else {
      let out = '';
      while (i < n && /[A-Za-z0-9_]/.test(line[i])) out += line[i++];
      if (!out) continue;
      value = out;
    }

    skipWs();
    if (i < n && line[i] !== '#') continue;

    Object.defineProperty(result, key, {
      value: value,
      enumerable: true,
      writable: true,
      configurable: true
    });
  }

  return result;
}
